import json, numpy as np
case = json.load(open('network.json'))
rep = json.load(open('report.json'))
T = case['time_periods']
tg = case['thermal_generators']; rg = case['renewable_generators']
names = [g['name'] for g in rep['thermal_generators']]
demand = np.array(case['demand']); resreq = np.array(case['reserves'])
U = np.array([g['commitment'] for g in rep['thermal_generators']], float)
P = np.array([g['production_MW'] for g in rep['thermal_generators']], float)
Rr = np.array([g['reserve_MW'] for g in rep['thermal_generators']], float)
ST = np.array([g['startup'] for g in rep['thermal_generators']], float)
SP = np.array([g['shutdown'] for g in rep['thermal_generators']], float)
REN = np.array([g['production_MW'] for g in rep['renewable_generators']], float)
rnames = [g['name'] for g in rep['renewable_generators']]
# name/order checks
assert names == list(tg.keys()) and rnames == list(rg.keys())
assert U.shape == (73, T) and P.shape == (73, T) and REN.shape == (81, T)
issues = []
TOL = 1e-4
for i, n in enumerate(names):
    g = tg[n]
    pmin, pmax = g['power_output_minimum'], g['power_output_maximum']
    cap = pmax - pmin
    for t in range(T):
        if U[i,t] not in (0,1): issues.append(('binary', n, t))
        if U[i,t]==0 and (abs(P[i,t])>TOL or abs(Rr[i,t])>TOL): issues.append(('offline-zero', n, t))
        if U[i,t]==1 and not (pmin-TOL <= P[i,t] <= pmax+TOL): issues.append(('limits', n, t))
        # above-min convention
        pam = max(P[i,t] - pmin, 0) if U[i,t] else 0
        # p+r headroom
        if P[i,t]+Rr[i,t] > pmax*U[i,t]+TOL: issues.append(('p+r>pmax', n, t))
        if Rr[i,t] > g['ramp_up_limit']+TOL: issues.append(('r>rampup', n, t))
# ramping variants
for i, n in enumerate(names):
    g = tg[n]; pmin = g['power_output_minimum']; pmax = g['power_output_maximum']
    prev_u, prev_p = g['unit_on_t0'], g['power_output_t0']
    prev_pam = max(prev_p - pmin, 0) if prev_u else 0
    for t in range(T):
        pam = max(P[i,t]-pmin,0) if U[i,t] else 0
        # variant A: actual-MW, p+r up
        if prev_u==1 and U[i,t]==1:
            if P[i,t]+Rr[i,t]-prev_p > g['ramp_up_limit']+TOL: issues.append(('A-up', n, t))
            if prev_p-P[i,t] > g['ramp_down_limit']+TOL: issues.append(('A-down', n, t))
        # variant B: above-min uniform
        if pam + Rr[i,t] - prev_pam > g['ramp_up_limit']+TOL: issues.append(('B-up', n, t))
        if prev_pam - pam > g['ramp_down_limit']+TOL: issues.append(('B-down', n, t))
        # startup/shutdown ramp caps
        if ST[i,t]==1 and P[i,t]+Rr[i,t] > g['ramp_startup_limit']+TOL: issues.append(('startup-ramp', n, t))
        if SP[i,t]==1 and prev_p > g['ramp_shutdown_limit']+TOL: issues.append(('stop-ramp', n, t))
        prev_u, prev_p, prev_pam = U[i,t], P[i,t], pam
# min up/down with initial
for i, n in enumerate(names):
    g = tg[n]; on = g['unit_on_t0']
    if on and 0 < g['time_up_t0'] < g['time_up_minimum']:
        if any(U[i,t]!=1 for t in range(g['time_up_minimum']-g['time_up_t0'])): issues.append(('init-up', n))
    if not on and 0 < g['time_down_t0'] < g['time_down_minimum']:
        if any(U[i,t]!=0 for t in range(g['time_down_minimum']-g['time_down_t0'])): issues.append(('init-dn', n))
    for t in range(T):
        if ST[i,t]==1 and any(U[i,tau]!=1 for tau in range(t, min(T,t+g['time_up_minimum']))): issues.append(('minup', n, t))
        if SP[i,t]==1 and any(U[i,tau]!=0 for tau in range(t, min(T,t+g['time_down_minimum']))): issues.append(('mindown', n, t))
# renewables per-hour bounds
for j, n in enumerate(rnames):
    g = rg[n]
    for t in range(T):
        if not (g['power_output_minimum'][t]-TOL <= REN[j,t] <= g['power_output_maximum'][t]+TOL):
            issues.append(('ren-bounds', n, t))
# balance + reserve
bal = np.abs(P.sum(0)+REN.sum(0)-demand)
if bal.max() > TOL: issues.append(('balance', bal.max()))
if (resreq - Rr.sum(0)).max() > TOL: issues.append(('reserve', (resreq-Rr.sum(0)).max()))
# hourly summary consistency
hs = rep['hourly_summary']
for t in range(T):
    row = hs[t]
    assert row['hour'] == t+1
    for k, v in (('demand_MW',demand[t]),('thermal_generation_MW',P[:,t].sum()),('renewable_generation_MW',REN[:,t].sum()),('reserve_requirement_MW',resreq[t]),('scheduled_spinning_reserve_MW',Rr[:,t].sum())):
        if abs(row[k]-v) > 1e-3: issues.append(('summary', t, k))
# cost consistency (total-cost curve interpretation)
def pc(pts, mw):
    if mw <= pts[0][0]: return pts[0][1]
    if mw >= pts[-1][0]: return pts[-1][1]
    for (x0,y0),(x1,y1) in zip(pts,pts[1:]):
        if x0 <= mw <= x1: return y0 + (mw-x0)*(y1-y0)/(x1-x0)
def tier_cost(tiers, d):
    ch = tiers[0]
    for s in tiers:
        if s[0] <= d: ch = s
        else: break
    return ch[1]
cost = 0.0
for i, n in enumerate(names):
    g = tg[n]
    pts = sorted((p['mw'], p['cost']) for p in g['piecewise_production'])
    tiers = sorted((s['lag'], s['cost']) for s in g['startup'])
    offline = g['time_down_t0'] if not g['unit_on_t0'] else 0
    on = g['unit_on_t0']
    for t in range(T):
        if U[i,t]==1:
            cost += pc(pts, P[i,t])
            if ST[i,t]==1: cost += tier_cost(tiers, offline)
            offline = 0; on = 1
        else:
            offline = (offline+1) if not on or offline==0 and not g['unit_on_t0'] else offline
            if on: offline = 0
            offline += 1
            on = 0
print('recomputed cost: %.4f  reported: %.4f  diff: %.6f' % (cost, rep['summary']['objective_cost'], abs(cost-rep['summary']['objective_cost'])))
print('startups:', ST.sum(), 'shutdowns:', SP.sum(), 'reported:', rep['summary']['total_startups'], rep['summary']['total_shutdowns'])
print('ISSUES:', issues if issues else 'NONE — all adversarial variant checks pass')
"

