# cost consistency (total-cost curve interpretation)
def pc(pts, mw):
    if mw <= pts[0][0]: return pts[0][1]
    if mw >= pts[-1][0]: return pts[-1][1]
    for (x0,y0),(x1,y1) in zip(pts,pts[1:]):
        if x0 <= mw <= x1: return y0 + (mw-x0)*(y1-y0)/(x1-x0)
def tier_cost(tiers, d):
    ch = tiers[0]
    for s in tiers:
        if s[0] <= d: ch = s
        else: break
    return ch[1]
